      'Mostrar cuántos elementos están ocultos',
  'Toon alleen een deel van de bullets, tabel of grafiek. De oorspronkelijke data blijft in het bestand bewaard.':
      'Mostrar solo una parte de las viñetas, la tabla o el gráfico. Los datos originales se conservan en el archivo.',
  'Voor tabellen: kolomindex of naam om op te sorteren. Voor grafieken: naam van de reeks.':
      'Para tablas: índice o nombre de la columna por la que ordenar. Para gráficos: nombre de la serie.',
  'Online opslag is alleen beschikbaar in de desktopversie.':
      'El almacenamiento en línea solo está disponible en la versión de escritorio.',
  'Online opslag': 'Almacenamiento en línea',
  'Presentaties openen uit en opslaan naar WebDAV, S3 en git-repository’s, met versiebeheer en samenwerken via een forge. Een deel van deze paden is tot nu toe vooral tegen testomgevingen beproefd; kies dit bewust. Zonder de module werkt alles lokaal gewoon: mappen, bestanden en pakketten.':
      'Abre presentaciones desde WebDAV, S3 y repositorios git y guárdalas allí, con control de versiones y colaboración a través de una forge. Hasta ahora, parte de estos caminos se ha probado sobre todo contra entornos de prueba; elígelo con conocimiento de causa. Sin el módulo, todo lo local funciona con normalidad: carpetas, archivos y paquetes.',
  'Er staan al online verbindingen ingesteld; die blijven werken, net als wachtend werk in de wachtrij. Uit betekent alleen: geen nieuwe online verbindingen toevoegen.':
      'Ya hay conexiones en línea configuradas; siguen funcionando, igual que el trabajo pendiente en la cola. Desactivado solo significa: no añadir nuevas conexiones en línea.',
  'De module AI-assistentie staat uit, dus hier gebeurt niets. Zet hem aan bij Uitbreidingen. Wat je hieronder hebt ingesteld blijft staan.':
      'El módulo Asistencia de IA está desactivado, así que aquí no ocurre nada. Actívalo en Extensiones. Lo que hayas configurado abajo se conserva.',
  'Hulp bij alt-teksten, beschrijvingen en formuleringen. Aanzetten verstuurt nog niets: dat gebeurt pas nadat je zelf een backend hebt gekozen en, bij een clouddienst, uitdrukkelijk hebt bevestigd. Een lokale backend verlaat je computer niet.':
      'Ayuda con textos alternativos, descripciones y formulaciones. Activarlo aún no envía nada: eso solo ocurre después de que elijas tú mismo un backend y, con un servicio en la nube, lo confirmes expresamente. Con un backend local, nada sale de tu ordenador.',
  'Kies de backend op het tabblad AI-assistentie. Zolang daar niets staat, gebeurt er niets.':
      'Elige el backend en la pestaña Asistencia de IA. Mientras allí no haya nada, no ocurre nada.',
  'De voorbeelddia\'s van een sjabloon staan in het Engels. Naam en omschrijving volgen je eigen taal; de inhoud pas je na het aanmaken aan.':
      'Las diapositivas de ejemplo de una plantilla están en inglés. El nombre y la descripción siguen tu propio idioma; el contenido lo adaptas después de crearla.',
  'Meer': 'Más',
  'Leesbaarheid van dit profiel': 'Legibilidad de este perfil',
  'Alle onderdelen halen de norm.': 'Todos los elementos cumplen la norma.',
  'Deze verhoudingen gaan over de app zelf, niet over je dia\'s.':
      'Estas proporciones se refieren a la propia aplicación, no a tus diapositivas.',
  'Tekst op kaarten en dialogen': 'Texto en tarjetas y diálogos',
  'Tekst op de schermachtergrond': 'Texto sobre el fondo de pantalla',
  'Tekst en pictogrammen in de zijbalk': 'Texto e iconos en la barra lateral',
  'Titel in de bovenbalk': 'Título en la barra superior',
  'Tekstknoppen en links': 'Botones de texto y enlaces',
  'Selectievakjes, schakelaars en de tekstcursor':
