  '1 slide achtergehouden door haar TLP': '1 diapositiva retenida por su TLP',
  'slides achtergehouden door hun TLP': 'diapositivas retenidas por su TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Estas diapositivas no se incluyen al presentar, al exportar ni en el paquete. Sube el nivel TLP de la presentación en Información de la presentación para incluirlas.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Todas las diapositivas están retenidas por su clasificación TLP: no hay nada que mostrar.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Todas las diapositivas están retenidas por su clasificación TLP: no hay nada que exportar.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Todas las diapositivas están omitidas o retenidas por su clasificación TLP: no hay nada que mostrar.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Todas las diapositivas están omitidas o retenidas por su clasificación TLP: no hay nada que exportar.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Las cifras de los gráficos no se han guardado: solo existen en esta ventana:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'En el navegador no hay recuperación tras un fallo: si cierras esta pestaña, el trabajo sin guardar se pierde. Guarda tú mismo la presentación.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  La base de datos CVE local (el que inicia la descarga eres tú): OciDeck obtiene los datos masivos a través de api.github.com y el archivo de versión al que apunta esa dirección.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Búsqueda de CVE (desactivada de forma predeterminada): si está activada, el término de búsqueda va al espejo CVE configurado y, si este no encuentra nada, a la base de datos europea de ENISA y a MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Un vídeo de YouTube o Vimeo incrustado carga el reproductor desde ese servicio.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  En el navegador: si el navegador se niega a obtener una dirección directamente, OciDeck lo reintenta a través del servidor del que procede la aplicación; esa dirección llega entonces a ese servidor.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'La retirada no se ha guardado. En el próximo inicio su consentimiento vuelve a ser válido.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Un subtítulo de sección que anuncia una nueva parte de la presentación. Mantenlo breve. Añade una imagen de fondo desde la biblioteca de imágenes.',
  'Bronnen doorzoeken…': 'Buscando en las fuentes…',
  'Niet doorzocht': 'No buscado',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Esta comprobación no se ejecuta en la versión web: la detección de rostros necesita una biblioteca del sistema que el navegador no tiene. Usa la versión de escritorio para revisar rostros en las imágenes.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'El token necesita acceso de lectura y escritura al repositorio. Gitea y Forgejo no tienen búsqueda en el servidor; OciDeck busca en local.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'El token necesita el ámbito repo (o granular: Contents de lectura y escritura).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'El token necesita read_repository, write_repository y read_api. La búsqueda en el servidor requiere Advanced o Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Búsqueda rápida en el servidor — por el retardo de indexación, puede faltar una presentación modificada hace poco.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Los medios no se conservan en un archivo .md simple',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Las imágenes, el vídeo y el audio que elegiste en esta pestaña solo existen en memoria. Un archivo .md simple no los conserva: se perderán al reabrirlo. Exporta como paquete .ocideck para llevarte los medios.',
  'Media verwijderd om privacyredenen':
      'Medios eliminados por motivos de privacidad',
  'Afbeeldingen door AI laten taggen?':
      '¿Dejar que la IA etiquete estas imágenes?',
