  'Nu': 'Ahora',
  'Vorige rapportage': 'Informe anterior',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Un cuadro de resultados muestra como máximo cinco cifras; más ya no se lee como un juicio.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Deja vacío el informe anterior si aún no había medición; la diapositiva no mostrará ningún cambio.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Determina si una subida se colorea de verde o de rojo. La flecha siempre sigue las cifras.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Unas pocas cifras clave junto a la cifra del informe anterior, para que el cambio cuente la historia. Indica en cada una si subir es una buena o una mala noticia.',
  'Zekere vondsten als fout behandelen':
      'Tratar los hallazgos seguros como errores',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Normalmente un hallazgo seguro — un número de identidad, un IBAN, una dirección de correo — es un aviso que puede ignorar. Activado se convierte en un error, y entonces la exportación puede bloquearse si también tiene activada esa opción. Pensado para entornos donde esos datos realmente no deben salir. Los hallazgos inciertos siguen siendo un aviso.',
  'Medicare-nummer — een zorggegeven': 'número de Medicare — dato de salud',
  'bedrijfsnummer': 'número de sociedad',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'número de seguro médico (RAMQ) — dato de salud',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'número de seguro médico (OHIP) — dato de salud',
  'bedrijfsnummer (BN)': 'número de empresa (BN)',
  'zorgverlenersnummer (NPI)': 'número de proveedor sanitario (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'número de Medicare (MBI) — un dato de salud',
  'wacht op verbinding': 'esperando conexión',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Guardado en este ordenador, todavía no en el repositorio. Se enviará en cuanto haya conexión de nuevo — o ahora, con "Vaciar cola".',
  'Branch (optioneel)': 'Rama (opcional)',
  'let op: de standaardbranch is': 'atención: la rama predeterminada es',
  'jij werkt op': 'tú trabajas en',
  'werkgeversnummer (EIN)': 'número de empleador (EIN)',
  'laatste vier cijfers van een SSN': 'últimos cuatro dígitos de un SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'fecha de nacimiento, código postal y sexo juntos: esos tres suelen señalar a una sola persona, incluso sin nombre',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'El certificado de este servidor no es de confianza. En un servidor autoalojado puedes verlo y confiar en él en Ajustes → Almacenamiento.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'El certificado de este forge no es de confianza. En un forge autoalojado puedes verlo y confiar en él en Ajustes → Almacenamiento.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'El certificado de este punto de conexión no es de confianza. En un punto de conexión autoalojado puedes verlo y confiar en él en Ajustes → Almacenamiento.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'El certificado del forge no es de confianza: autofirmado, caducado o emitido a otro nombre.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'El certificado del punto de conexión no es de confianza: autofirmado, caducado o emitido a otro nombre.',
  'creditcardnummer': 'número de tarjeta de crédito',
  'beveiligingscode van een creditcard':
      'código de seguridad de la tarjeta (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'datos en las notas del orador: invisibles en la diapositiva, pero sí en la exportación',
  'Certificaat vertrouwen?': '¿Confiar en este certificado?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'El certificado de este servidor no está firmado por una entidad reconocida. Es normal en un servidor autoalojado, pero también es el aspecto de una conexión interceptada.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Compara la huella de abajo con la que muestra tu propio servidor. Si coinciden, estás hablando con la máquina correcta.',
  'Uitgegeven aan': 'Emitido para',
  'Uitgegeven door': 'Emitido por',
  'Geldig tot': 'Válido hasta',
  'Vingerafdruk (SHA-256)': 'Huella (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Solo se confía en este certificado. Si el servidor lo sustituye más adelante, OciDeck volverá a preguntar.',
  'Vertrouwen': 'Confiar',
  'Certificaat bekijken': 'Ver certificado',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Los lugares donde guardas y buscas tus presentaciones — carpetas en este ordenador, servidores WebDAV, buckets S3 y repositorios git mezclados. Arrástralos en el orden que quieras: el primero de cada tipo vale como predeterminado.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Almacenamiento S3: cuando te conectas a un bucket, se guardan el endpoint, el nombre del bucket y tu clave de acceso (la clave secreta de forma segura en el llavero de tu sistema) y las presentaciones que abres o guardas se envían a ese servicio de almacenamiento.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Almacenamiento Git: cuando te conectas a un repositorio, se guarda tu token de acceso (de forma segura en el llavero de tu sistema) y las presentaciones que guardas se envían a ese servidor como commits. Una copia de trabajo del repositorio permanece sin cifrar en este dispositivo.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Faltan los nombres de enfermedades para el idioma de esta presentación. La religión, la opinión política y los términos sindicales sí se reconocen, y los patrones con dígito de control (DNI, IBAN, pasaporte) siempre funcionan, pero no cuentes con que se detecte un diagnóstico.',
  'niet getest': 'sin probar',
  'Werkte op': 'Funcionó el',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Has iniciado sesión, pero no tienes acceso aquí. Tu contraseña no es el problema: pide al administrador permisos sobre esta carpeta.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Tu token es válido, pero no tiene permiso para esto. Dale más permisos, o espera si la forja aplica un límite.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'El token es válido, pero no tiene permiso para esto: dale más permisos sobre el repositorio.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Sesión iniciada, pero sin acceso: tu contraseña no es el problema. Pide permisos sobre esta carpeta.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Esto parece una URL DAV completa. Con Nextcloud, OciDeck deduce esa ruta por sí mismo: aquí solo va el servidor.',
  'Overnemen': 'Aplicar',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV no está (bien) configurado — comprueba los datos del servidor en Ajustes → Almacenamiento.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'El repositorio git no está (bien) configurado — comprueba servidor, propietario y repositorio en Ajustes → Almacenamiento.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'El nombre del servidor de la forja no existe o no se puede resolver. Comprueba si hay una errata en la URL del servidor.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Esta forja tiene una dirección privada o de LAN. Márcala como interna de confianza en Ajustes → Almacenamiento.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'La forja no es accesible — comprueba tu conexión y la URL del servidor.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Error al iniciar sesión en la forja. Comprueba tu token: necesita acceso de lectura al repositorio y de escritura para guardar.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'No encontrado en el repositorio — o tu token no puede verlo.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'La forja devolvió un error. Inténtalo de nuevo más tarde.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Esta dirección no responde como una forja. ¿Es correcto el tipo de forja en Ajustes → Almacenamiento?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Configura primero un servidor WebDAV en Ajustes → Almacenamiento.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Necesario cuando la forja está en una red privada o doméstica. Sin esta opción, la comprobación de seguridad rechaza una dirección privada.',
  'Vul server-URL, eigenaar en repository in':
      'Rellena la URL del servidor, el propietario y el repositorio',
  'de standaardbranch heet': 'la rama predeterminada se llama',
  'die wordt voortaan gebruikt': 'se usará a partir de ahora',
  'de repository is nog leeg; de eerste opslag vult hem':
      'el repositorio aún está vacío; el primer guardado lo llenará',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'atención: este token solo puede leer, así que guardar fallará',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Error de inicio de sesión — comprueba el token. Necesita acceso de lectura al repositorio y de escritura para poder guardar.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repositorio no encontrado — o tu token no puede verlo. Comprueba el propietario y el nombre del repositorio.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Esta dirección no responde como una forja. ¿Es correcto el tipo de forja elegido?',
  'kenteken': 'matrícula del vehículo',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'No hay una lista de palabras clave para categorías especiales de datos personales en el idioma de esta presentación. Los patrones con dígito de control (DNI, IBAN, pasaporte) sí funcionan; palabras como «diagnóstico» o «sospechoso» no se reconocen.',
  'Landpakketten voor identificatienummers':
      'Paquetes de país para números de identificación',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Números como el BSN neerlandés o el PESEL polaco son propios de cada país. Toda Europa está activada porque la mayoría de esos números llevan un dígito de control: activarlos casi no cuesta falsas alertas. IBAN, correo, secretos y bandas de pasaporte son independientes y siempre se comprueban.',
