  'Je eigen gegevens': 'Tus propios datos',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Uno por línea: tu nombre, dirección de correo, teléfono o el dominio de tu organización. Lo que pongas aquí no se notifica ni se redacta: es el remitente, no un hallazgo. Un dominio (example.org) cubre todas las direcciones bajo él.',
